e", "price_field", "price", "source", "kind", "direction"], "title": "Trigger", "type": "object"}, "TriggerSource": {"additionalProperties": false, "properties": {"timeframe": {"const": "M15", "title": "Timeframe", "type": "string"}, "bar_index": {"minimum": 0, "title": "Bar Index", "type": "integer"}, "open_time_ms": {"minimum": 0, "title": "Open Time Ms", "type": "integer"}, "close_time_ms": {"minimum": 0, "title": "Close Time Ms", "type": "integer"}}, "required": ["timeframe", "bar_index", "open_time_ms", "close_time_ms"], "title": "TriggerSource", "type": "object"}}, "additionalProperties": false, "properties": {"schema": {"const": "brooks.trade-intent.v2", "title": "Schema", "type": "string"}, "role": {"const": "TRADER", "title": "Role", "type": "string"}, "decision": {"enum": ["ENTER_LONG", "ENTER_SHORT", "NO_TRADE"], "title": "Decision", "type": "string"}, "symbol": {"title": "Symbol", "type": "string"}, "decision_time_ms": {"minimum": 0, "title": "Decision Time Ms", "type": "integer"}, "market_context": {"anyOf": [{"additionalProperties": true, "type": "object"}, {"type": "null"}], "title": "Market Context"}, "setup": {"anyOf": [{"$ref": "#/$defs/Setup"}, {"type": "null"}]}, "decision_timeframe": {"anyOf": [{"const": "M15", "type": "string"}, {"type": "null"}], "title": "Decision Timeframe"}, "context_timeframes_used": {"items": {"type": "string"}, "title": "Context Timeframes Used", "type": "array"}, "entry_mechanism": {"enum": ["continuation", "breakout", "breakout_pullback", "reversal", "none", "unclear"], "title": "Entry Mechanism", "type": "string"}, "trigger": {"anyOf": [{"$ref": "#/$defs/Trigger"}, {"type": "null"}]}, "invalidation": {"anyOf": [{"$ref": "#/$defs/PriceReference"}, {"type": "null"}]}, "evidence_for": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence For", "type": "array"}, "evidence_against": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence Against", "type": "array"}, "qualitative_confidence": {"enum": ["high", "medium", "low"], "title": "Qualitative Confidence", "type": "string"}, "uncertainty": {"items": {"type": "string"}, "minItems": 1, "title": "Uncertainty", "type": "array"}, "conditions_that_change_market_read": {"items": {"type": "string"}, "minItems": 1, "title": "Conditions That Change Market Read", "type": "array"}}, "required": ["schema", "role", "decision", "symbol", "decision_time_ms", "market_context", "setup", "decision_timeframe", "context_timeframes_used", "entry_mechanism", "trigger", "invalidation", "evidence_for", "evidence_against", "qualitative_confidence", "uncertainty", "conditions_that_change_market_read"], "title": "TradeIntentV2", "type": "object"}
Input: {"decision_time_ms": 1790121599999, "macro_contexts": {"D1": {"context": {"always_in": "long", "always_in_relevance": "medium", "breakout_mode": false, "confidence": "medium", "decision_time_ms": 1790035199999, "directional_pressure": "bull", "evidence_against": ["The strongest counterargument: the largest single directional move in the window is the opening 12-bar, ~36% bear leg to 1368.42, so the bull-trend label rests only on the last ~34 bars, and the 73 bars before that are balance, not trend.", "The 27 bars ahead of the final push are a two-sided range (2357.18-2680) with heavy overlap and mid-range closes; 2850 is a first-bar probe only 79.00 above 2771, and single-bar breakouts of multi-week range tops often fail and re-enter the range.", "Bar 1787270400000 (445.69 range, close 2515.30, ~255.70 upper tail) followed by a 27-bar stall is spike-high behavior consistent with a temporary exhaustion and a market capped by a range boundary rather than a functioning bull channel.", "The 208.30-point final bar after an extended advance could be a buy climax; a large bull bar that is immediately retraced would mark exhaustion rather than breakout acceptance."], "evidence_for": ["A 388.17-point bull trend bar (1787097600000) closed at 2252.16, 89% of its range and above the 73-bar range top 1974.46, with immediate follow-through to 2771 two bars later.", "Successive higher swing highs across the window (1974.46, 2293.80, 2771, 2850) and higher swing lows (1368.42, 1512.91, 2357.18/2358.62).", "The 27-bar pause held entirely above the breakout bar's open 1916.51 and the old range top 1974.46; no close returned inside the 73-bar range.", "The final bar closes 2775.61 above the prior spike high 2771 and in the upper 64% of its range, with four consecutive rising closes."], "missing_information": [], "observations": ["The window opens at 2109.85 (close of 1779667200000) after a 2139.34 high, then declines 13 bars to 1368.42 (low of 1780704000000), about 36% below 2139.34.", "Bar 1780704000000 has a 230.85 range with a 200.13 lower tail and closes at 1568.55 (top ~13% of its range); bar 1780790400000 (open 1568.55, high 1690.78, low 1563.52, close 1687.83) is a bull reversal bar closing at its high.", "From 1780790400000 to 1787011200000 (73 bars) price overlaps repeatedly between 1512.91 (low of 1782432000000) and 1974.46 (high of 1785110400000); closes cluster 1550-1950 with many overlapping bodies and mixed closes (two-sided range).", "Bar 1787097600000 breaks out: open 1916.51, high 2293.80, low 1905.63, close 2252.16, a 388.17-point bull trend bar closing in the top ~11% of its range and above the 1974.46 range top.", "Bar 1787270400000 spikes to 2771 with a 445.69 range, closing 2515.30 and leaving a ~255.70 upper tail.", "Bars 1787184000000 through 1789603200000 (27 bars) stay between 2357.18 (low of 1788307200000) and 2680 (high of 1789084800000); bodies overlap and closes sit mostly 2380-2530.", "The last four closes are 2612.02, 2632.98, 2642.90, 2775.61; the final bar (open 2642.90, high 2850, low 2641.70, close 2775.61) closes above the prior spike high 2771 in the upper 64% of its 208.30-point range."], "phase": "breakout-spike", "primary_regime": "bull-trend", "role": "CONTEXT_ANALYST", "schema": "brooks.market-context.v2", "structures": [{"description": "Bear leg of 13 bars from the window high 2139.34 into the 1368.42 low of 1780704000000; bar ranges expand into the low and that bar closes 1568.55 with a 200.13 lower tail, followed by a bull reversal bar at 1687.83.", "end_time_ms": 1780790399999, "kind": "climax", "lower_boundary": "1368.42", "start_time_ms": 1779667200000, "upper_boundary": "2139.34"}, {"description": "73-bar two-sided range from 1780790400000 to 1787011200000; repeated overlap between 1512.91 and 1974.46 with a slight upward tilt after the 1512.91 low, many inside bars and closes in the middle of the range.", "end_time_ms": 1787183999999, "kind": "range", "lower_boundary": "1512.91", "start_time_ms": 1780790400000, "upper_boundary": "1974.46"}, {"description": "Bull spike escaping the 73-bar range: bar 1787097600000 opens 1916.51 and closes 2252.16 above the 1974.46 range top, with follow-through to the 2771 spike high of 1787270400000.", "end_time_ms": 1787356799999, "kind": "breakout", "lower_boundary": "1905.63", "start_time_ms": 1787097600000, "upper_boundary": "2771"}, {"description": "Post-spike pause of 27 bars between the 2357.18 low of 1788307200000 and the 2680 high of 1789084800000; most highs sit 2520-2560 with probes to 2680 and most lows 2357-2440, heavy body overlap and mid-range closes.", "end_time_ms": 1789689599999, "kind": "range", "lower_boundary": "2357.18", "start_time_ms": 1787184000000, "upper_boundary": "2680"}, {"description": "Final bull leg from the 2358.62 low of bar 1789430400000: 1789689600000 and 1789776000000 close 2612.02 and 2632.98, and 1789948800000 closes 2775.61 above the 2771 spike high. The breakout proper is bars 1789689600000-1789948800000.", "end_time_ms": 1790035199999, "kind": "breakout", "lower_boundary": "2436.87", "start_time_ms": 1789689600000, "upper_boundary": "2850"}], "symbol": "ETH-USDT", "timeframe": "D1", "transition_conditions": ["Bull continuation: several consecutive closes holding above 2700 (high of 1789776000000) and above 2771, with higher lows above 2641.70, would confirm acceptance above the spike high and strengthen the bull-trend/breakout-spike read.", "Failed breakout: a close back below 2641.70 (low of the final bar), followed by a close below 2568.16 (low of 1789862400000), would signal the breakout failed and shift the read back toward the 2357.18-2680 range.", "Range reassertion: a close back below 2357.18 with follow-through would turn the post-spike structure into a top and recast the 1787097600000 advance as a bull trap.", "Trend weakening: deeper pullbacks that overlap prior swing lows together with more bear bars closing near their lows would move the phase from breakout-spike toward channel or range.", "Climax risk: a further outsized bull bar immediately followed by a bear bar closing near its low would argue for a buy climax rather than a sustained second leg."], "window_bars": 120}, "freshness": "stale"}, "H4": {"context": {"always_in": "long", "always_in_relevance": "high", "breakout_mode": true, "confidence": "medium", "decision_time_ms": 1790107199999, "directional_pressure": "bull", "evidence_against": ["The breakout bar opening 1789977600000 closed at 2723.15, only about 34% of its 191.94-point range (lower third), so sellers were active at 2850; a weak close on the widest bar of the window is consistent with a buy climax rather than clean acceptance.", "The same pattern failed twice earlier in the window: the 1789128000000 spike (high 2680, close 2555.52, mid-range close) was followed by about 20 bars of range and the 1789416000000 spike (high 2609.02, close 2514.07) was followed by the collapse to 2358.62, so failed upside spikes are the established behavior in this data.", "About 100 of the 120 supplied bars are two-sided overlapping range trade between 2358.62 and 2700; the trend leg is only the final third of the window, so the breakout above 2700 is fresh (9 bars) and unconfirmed by time.", "Since the 2850 spike high, highs have been stepping down (2795, 2770, 2804.59, 2776.18, 2761.62, 2761.63) with overlapping small bodies and no wide continuation bar, so the post-breakout action shows no acceleration; bar opening 1790049600000 traded back to 2716.01, only about 16 points above the broken 2700 level."], "evidence_for": ["Higher highs and higher lows run for roughly 43 bars: lows 2358.62 -> 2384.29 -> 2438.33 -> 2569.8 -> 2716.01, highs 2585.5 -> 2643.52 -> 2700 -> 2850, with no close below the prior swing low in that leg.", "Bar opening 1789977600000 cleared the multi-week 2700 ceiling with the widest range of the window (2658.06-2850) and closed 2723.15 above it; the bars that followed closed 2754.31, 2760.51 and 2775.61, all above 2700, so the breakout has follow-through in both highs and closes.", "Trend bars in the leg show buyers closing bars near their highs: bar opening 1789732800000 closed 2578.6 against a 2585.5 high and the next bar closed 2636.28 against a 2643.52 high, and the 1789977600000-1790020800000 sequence produced successive new window highs.", "The last five bars are a shallow, tight pause (2716.01-2776.18) that never closes back inside the old 2700 range and never tests the 2569.8 higher low, which is the classic bull-flag behavior after a trend leg and keeps the Always-In long intact."], "missing_information": [], "observations": ["Window is 120 closed H4 bars, first open 1788379200000, last bar open 1790092800000 and close 1790107199999; window low 2358.62 (bar opening 1789488000000), window high 2850 (bar opening 1789977600000).", "Bars opening 1788523200000 through 1789963200000 stay inside a wide two-sided range: repeated tests of the 2680-2700 area above (highs 2680 at 1789128000000; 2700 at 1789804800000 and 1789948800000) and of the 2411-2358.62 area below (lows 2411.04 at 1789041600000; 2390.73 at 1789473600000; 2358.62 at 1789488000000), with heavy bar-to-bar overlap.", "Two upside spikes inside that range failed: bar opening 1789128000000 (open 2457.12, high 2680, close 2555.52, roughly mid-range) and bar opening 1789416000000 (high 2609.02, close 2514.07) were each followed by declines, the second reaching the window low.", "Bar opening 1789977600000 is the widest bar of the window: open 2658.81, high 2850, low 2658.06, close 2723.15, i.e. it closes in the lower third of its 191.94-point range after clearing the prior 2700 high.", "From the 2358.62 low, lows rise to 2384.29 (1789560000000), 2438.33 (1789675200000), 2569.8 (1789862400000) and 2716.01 (1790049600000), while highs progress 2585.5 (1789732800000), 2643.52 (1789747200000), 2700, 2700, 2850 and then 2804.59 (1790020800000).", "Last five bars (opens 1790035200000-1790092800000) overlap inside 2716.01-2776.18 with closes 2738.87, 2724.95, 2740.2, 2742.31 and 2749.43, all holding above the 2700 level; the lowest close since the 1789977600000 breakout bar is 2724.95."], "phase": "channel", "primary_regime": "bull-trend", "role": "CONTEXT_ANALYST", "schema": "brooks.market-context.v2", "structures": [{"description": "Dominant multi-week two-sided range: about 100 bars of overlapping trade between the 2358.62 low and the 2700 ceiling, with failed upside spikes at 2680 (bar opening 1789128000000) and 2609.02 (bar opening 1789416000000), repeated returns into the 2411-2569 area, and no sustained acceptance beyond either edge until the bar opening 1789977600000. Upper boundary is the 2700 high printed by the bars opening 1789804800000 and 1789948800000; lower boundary is the 2358.62 low of the bar opening 1789488000000.", "end_time_ms": 1789963200000, "kind": "range", "lower_boundary": "2358.62", "start_time_ms": 1788523200000, "upper_boundary": "2700"}, {"description": "Sharp bear leg with climactic character: from the 2609.02 high of the bar opening 1789416000000 down to the 2358.62 low of the bar opening 1789488000000, driven by two consecutive wide bear bars (closes 2423.29 then 2412.95). It ended the range's downside probe and is the origin of the current bull leg.", "end_time_ms": 1789488000000, "kind": "swing", "lower_boundary": "2358.62", "start_time_ms": 1789416000000, "upper_boundary": "2609.02"}, {"description": "Bull trend from the 2358.62 low: higher lows 2358.62 -> 2384.29 -> 2438.33 -> 2569.8 -> 2716.01 and higher highs 2585.5 -> 2643.52 -> 2700 -> 2850, built from two wide bull bars (opens 1789732800000 and 1789977600000) separated by an overlapping 2569.8-2700 pullback leg. Slope is moderate, bars overlap, and each advance is followed by a pause rather than by sustained acceleration.", "end_time_ms": 1790107199999, "kind": "channel", "lower_boundary": "2358.62", "start_time_ms": 1789488000000, "upper_boundary": "2850"}, {"description": "Bar opening 1789977600000 broke the long-standing 2700 ceiling and closed 2723.15 above it, with follow-through highs of 2795 (1789992000000) and 2804.59 (1790020800000) and closes 2754.31, 2760.51 and 2775.61; every close since the breakout remains above 2700. Price has not yet separated far from the broken level, and the follow-through high 2804.59 is below the 2850 spike high.", "end_time_ms": 1790107199999, "kind": "breakout", "lower_boundary": "2700", "start_time_ms": 1789977600000, "upper_boundary": "2804.59"}, {"description": "Tight five-bar pause at the highs after the breakout: bars opening 1790035200000 through 1790092800000 hold inside 2716.01-2776.18 with overlapping small bodies and closes between 2724.95 and 2749.43. It sits just below the 2804.59 follow-through high and above the 2700 breakout level, so it reads as a flag at the top of the bull leg rather than as a separated new range.", "end_time_ms": 1790107199999, "kind": "range", "lower_boundary": "2716.01", "start_time_ms": 1790035200000, "upper_boundary": "2776.18"}], "symbol": "ETH-USDT", "timeframe": "H4", "transition_conditions": ["Bull acceptance: a wide-range bar closing above the 2804.59 high of the bar opening 1790020800000 would confirm the 2700 breakout and argue for a fresh spike/continuation phase rather than a flag at the highs.", "Failed breakout: a strong bear bar closing in its lower third below 2700 would signal rejection of the spike and shift the read back toward the 2569.8-2700 trading range.", "Trend break: trade below 2569.8 (low of the bar opening 1789862400000) would end the higher-low sequence and move the classification toward trading-range or transition-unclear with the Always-In flipping short.", "Time/overlap test: more than roughly 10 bars of continued overlap inside 2716.01-2776.18 without a new high would describe a completed spike followed by a channel-to-range phase at the highs.", "Continued defense of 2716.01 with successive closes above 2761.63 would keep the bull channel intact, while repeated failure at 2776.18 would describe a small range forming under the 2850 spike high."], "window_bars": 120}, "freshness": "stale"}}, "raw": {"H1": [{"close": "2446.89", "close_time_ms": 1789693199999, "high": "2446.89", "low": "2436.87", "open": "2446.22", "open_time_ms": 1789689600000, "volume": "2250317.206"}, {"close": "2457.2", "close_time_ms": 1789696799999, "high": "2458.47", "low": "2445.26", "open": "2446.89", "open_time_ms": 1789693200000, "volume": "1825586.474"}, {"close": "2463", "close_time_ms": 1789700399999, "high": "2465.17", "low": "2452.08", "open": "2457.85", "open_time_ms": 1789696800000, "volume": "1939084.233"}, {"close": "2476.78", "close_time_ms": 1789703999999, "high": "2482.09", "low": "2460.68", "open": "2463", "open_time_ms": 1789700400000, "volume": "2022411.123"}, {"close": "2480.3", "close_time_ms": 1789707599999, "high": "2480.35", "low": "2469.24", "open": "2476.75", "open_time_ms": 1789704000000, "volume": "2198637.447"}, {"close": "2477.97", "close_time_ms": 1789711199999, "high": "2488.29", "low": "2476.81", "open": "2480.3", "open_time_ms": 1789707600000, "volume": "2082065.695"}, {"close": "2486.27", "close_time_ms": 1789714799999, "high": "2486.37", "low": "2477.9", "open": "2477.97", "open_time_ms": 1789711200000, "volume": "1757756.356"}, {"close": "2488.06", "close_time_ms": 1789718399999, "high": "2495.99", "low": "2486.12", "open": "2486.27", "open_time_ms": 1789714800000, "volume": "1805192.22"}, {"close": "2503.1", "close_time_ms": 1789721999999, "high": "2504.1", "low": "2486.12", "open": "2488", "open_time_ms": 1789718400000, "volume": "2367824.773"}, {"close": "2507.2", "close_time_ms": 1789725599999, "high": "2517.53", "low": "2501.73", "open": "2503.1", "open_time_ms": 1789722000000, "volume": "2022095.258"}, {"close": "2512.89", "close_time_ms": 1789729199999, "high": "2519.81", "low": "2507.18", "open": "2507.2", "open_time_ms": 1789725600000, "volume": "1881729.637"}, {"close": "250